import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"KPTI 在 OS","description":"","frontmatter":{"title":"KPTI 在 OS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kpti-os.md","filePath":"cs/kpti-os.md","lastUpdated":1789023840000}'),h={name:"cs/kpti-os.md"};function P(T,a,m,u,E,_){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="kpti-在-os" tabindex="-1">KPTI 在 OS <a class="header-anchor" href="#kpti-在-os" aria-label="Permalink to &quot;KPTI 在 OS&quot;">​</a></h1><div class="epigraph"><p>KPTI 给用户运行一套几乎不含内核的页表，陷入再切回完整内核页表，使 Meltdown 一类通过缓存推测读内核的路径变难。</p><footer>—— 据 Linux KPTI 文档；Lipp et al., Meltdown；Corbet 对页表隔离的 LWN 整理</footer></div><p><a href="/cs/direct-map-highmem">直接映射</a> 让内核页框在内核页表里可走。<a href="/cs/user-kernel-split">用户/内核分裂</a> 靠用户位，但推测执行可绕过。缺口是 <strong>KPTI（页表隔离）</strong> 在 OS 的代价：CR3 切换与 trampoline。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Meltdown：用户推测加载内核直映地址，把秘密抽进缓存。缓解：用户 CR3 指向不含内核直映的表（仅少量入口trampoline）。系统调用/中断：切到内核 CR3。缺口：PCID 减少 TLB 全刷；无 PCID 则每次陷入射 TLB，syscall 变贵。本课不把 Spectre 各变体的微码写成清单。</p><p><span class="marginnote">nopti 可关。有硬件 Meltdown 免疫的 CPU 内核会自动弱化隔离。对象是页表根，不是 LSM。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>fork/exec：为进程准备两套 pgd 或切换视图。进入内核：trampoline 栈 + 切 CR3。对照 <a href="/cs/rss-multiqueue">RSS</a>：性能税在陷入路径。对照 vmalloc：内核页仍在内核表里。对照 <a href="/cs/napi">NAPI</a>：中断也要切表。</p>',8)),(e(),n(c,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%20CR3%20%E6%9C%80%E5%B0%8F%E5%86%85%E6%A0%B8%22%5D%20--%3E%20SYSC%5B%22%E9%99%B7%E5%85%A5%22%5D%0A%20%20SYSC%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%20CR3%20%E5%AE%8C%E6%95%B4%E6%98%A0%E5%B0%84%22%5D%0A%20%20K%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%86%8D%E5%88%87%E5%9B%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>KPTI 用页表切换换推测执行隔离，把 Meltdown 从「必中」变成「用户页表里没有那地址」。税是 TLB 与 CR3。不要写成密码学。与 <a href="/cs/cgroups">cgroup</a> 无关。后课加固还会加更多：SMEP、KASLR。</p><p>调试：kprobes 在隔离下仍要能跑，入口路径变复杂。</p><p>实现上：PCID 让两套 pgd 的 TLB 项共存，否则每次 syscall 射 TLB。trampoline 栈避免用用户 RSP 进核。硬件免疫 Meltdown 的 CPU 可编译或运行时弱化 KPTI。 读法上只引用<a href="/cs/direct-map-highmem">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>KPTI 在 OS</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 L1TF 的全部 KVM 特例——虚拟化后课会再遇。不保证 32 位 pae 的同一实现。下一课把若干加固开关收成一课：内核加固。</p><p>版本字段会变，课序钉的是机制对象「KPTI 在 OS」，不是某一主线内核的结构体名。 后课默认：用户运行时可不见内核直映。更多加固原语（SMEP/SMAP/CFI 等），下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KPTI 用双页表减少用户推测读内核。</li><li>陷入切 CR3，PCID 减 TLB 税。</li><li>内核加固是下一课。</li><li>出处：Linux KPTI；Meltdown 论文；LWN。</li></ul>',11))])}const C=l(h,[["render",P]]);export{f as __pageData,C as default};
